For every constant $C > 0$, there is a constant $C^*$ such that whenever the parameter $p \in [0,1]$ satisfies
  \begin{equation}

q \ge 680\left( \frac{3(C + 4)\log N}{\hat n}\right)^{1/4}
  \end{equation}
  and
	\begin{equation}

1\ge\gamma :=
	\begin{cases}
		C^* \left( p^2 \mathbb I + \sqrt{\frac{\log N}{p\hat n }}\right), \quad & p \le 0.49 \\
	C^* \left( q^{3/2}\mathbb I + \left(\frac{\log N}{\hat n} \right)^{1/4} + \frac1q\sqrt{\frac{\log N}{\hat n}} \log \frac{\hat n}{\log N}\right), \quad & p > 0.49,
	\end{cases}
\end{equation}
there is, for $m := \lceil(1-\gamma)pN\rceil$, a joint distribution of random graphs $\mathbb G(n_1,n_2,m)$ and $\mathbb R(n_1,n_2,p)$ such that
\begin{equation}

	    \mathbb {P}\left(\mathbb G(n_1,n_2,m) \subseteq \mathbb R(n_1,n_2,p)\right) = 1 - O(N^{-C}).
    \end{equation}
    If, in addition $\gamma \le 1/2$, then for $p' := (1 - 2\gamma)p$,
	there is a joint distribution of $\mathbb G(n_1,n_2,p')$ and $\mathbb R(n_1,n_2,p)$ such that
\begin{equation}

  \mathbb {P}\left(\mathbb G(n_1,n_2,p') \subseteq \mathbb R(n_1,n_2,p)\right) = 1 - O(N^{-C}).
    \end{equation}

For every constant $C > 0$, if assumptions~(26),~(27), and~(28) hold, then
\begin{equation}

  \mathbb {P}\left({\mathcal{A}}\right) = 1- O(N^{-C}),
\end{equation}
where the constant implicit in the $O$-term in~(31) may also depend on $C$.

We have
\begin{equation}

  \operatorname{\mathbb{E}} |S| \ge t_0 - \theta M,
\end{equation}
where
 \begin{equation*}
	\theta := 1080 \hat p^2 \mathbb I +
	\begin{cases}
	  6480\sqrt{\frac{2(C + 3)\log N}{p\hat n}}, &\quad  p \le 0.49, \\
		6250\sqrt{\frac{(C + 3)\log N}{q^2\hat n }  }\log \frac{\hat n}{\log N}, &\quad  p > 0.49,
	\end{cases}
\end{equation*}
and, with $\gamma$ as in~(5),
\begin{equation}

  \gamma  \ge \tau_0 + \theta  + 2/M + \sqrt{\frac{2C \log N}{M}}.
\end{equation}

For every constant $C > 0$, under the conditions of Lemma~6,
\begin{equation*}
  \mathbb {P}\left(\mathbb R(t) \text{ is } \delta(t)\text{-typical for all } t < t_0\right) = 1 - O(N^{-C}).
\end{equation*}

For every constant $C>0$, under the conditions of Lemma~6, for $i \in [2]$ we have that with probability $1 - O(N^{-C})$, 
	\begin{equation}

	  \mathbb {P}\left( \max_{u,v \in V_i, u \neq v} \left|\frac{\theta_t(u,v)}{\tau qd_{i} } - 1\right| > \delta(t)\,|\,\mathbb R(t)\right) \le e^{ - 2\lambda(t) }, \qquad \text{for all  } t < t_0.
	\end{equation}

For every constant $C > 0$, under the conditions of Lemma~6, with probability $1 - O(N^{-C})$
\begin{equation}

	\min_{e, f \in K \setminus \mathbb R(t), e \neq f}\mathbb {P}\left(e \in \mathbb R, f \notin \mathbb R\,|\,\mathbb R(t)\right) \ge e^{ - \lambda(t) }, \qquad \text{for all } t < t_0.
\end{equation}

Let $r, b \in (0,1)$ be real numbers and define $\alpha := \min \{r,b\}$.
	Let $\nu<\alpha/16$ and $\delta \leq \alpha/16$ be positive reals and
	let $F \subseteq K$ be a $(r, b, \delta)$-regular, $(b + r, \delta)$-jumbled bipartite blue-red graph. If sets $X \subseteq V_i$, $Y \subseteq V_{3-i}$ satisfy
\begin{equation}

	\varepsilon_{B}(X,\overline{Y}) + \varepsilon_{R}(\overline{X},Y) \le \nu,
\end{equation}
and
\begin{equation}

	\min \{bs(X),rs(Y)\} \leq \frac{rb}{r + b},
\end{equation}
then
\begin{equation}

	\max \{bs(X), rs(Y)\} \le \frac{\nu}{1 - 7\delta/\alpha}.
\end{equation}

Let  $\alpha = \min \{ \tau p, q \}$ and $\pi := \tau p + q$. For every constant $C > 0$ and $p > 0.49$, if assumptions (27) and (28) hold,	then, with probability $1 - O(N^{-C })$, for all $t < t_0$
\begin{equation*}
	K \setminus \mathbb R(t)\quad \text{is} \quad(\pi, \alpha/16)\text{-jumbled}.
\end{equation*}
and for any $e \in K \setminus \mathbb R(t)$
\begin{equation*}
  K \setminus (\mathbb R(t) \cup \{ e \}) \quad \text{is} \quad(\pi, \alpha/16)\text{-jumbled}.
\end{equation*}

Let $F \subseteq K$ be a bipartite graph and  $\rho \in (0,1)$ and $\mu \ge 0$ be given. If
	\begin{equation}

		\min_{v \in V_1} \deg_F(v) \ge \rho n_2\quad\text{and}\quad\max_{u,v\in V_1} \operatorname{cod}_F(u,v) \le \rho^2n_2 + \mu,
	\end{equation}
then, for all $A \subseteq V_1$ and $B \subseteq V_2$,
	\begin{equation*}
		|e_F(A,B) - \rho|A||B|| \le \sqrt{(\rho n_2 + \mu |A|)|A||B|} + |B|\mathbb I_{\left\{ |A|\rho < 1 \right\}}.
	\end{equation*}

If $\lambda = \lambda(n_1,n_2) \le \tau_0 p \hat n$, then for $i = 1, 2$, with probability $1 - O(N^2e^{-9\lambda/4})$
\begin{equation}
  \forall t < t_0 \quad \forall v \in V_i \quad |\deg_{\mathbb R(t)}(v) - (1 - \tau) d_i| \le 3 \sqrt{\lambda \tau d_i}.

\end{equation}

Assume that $n_1 \ge n_2$ and $p > 0.49$.
	If $\lambda = \lambda(n_1,n_2) \ge \log N$, then,  with probability $1 - O(N^3e^{-\lambda/3 })$,
	\begin{equation}

		\forall t \le M \quad \forall u_1 \neq v_1 \quad\operatorname{cod}_{\mathbb R(t)}(u_1,v_1) \le(1 - \tau)^2p^2 n_{2} + 20 q^3n_2\mathbb I + 15\sqrt{\lambda n_{2}}.
	\end{equation}

Given any positive constants $a, b, C$ such that $a+b < 1/2$, there exists a constant $\epsilon > 0$ so that the following holds. Consider the set of degree sequences $\mathbf{d}_1,\mathbf{d}_2$ satisfying
\begin{romenumerate}
	\item $\max_{v \in V_1}|d_{1,v} - \bar d_1| \le Cn_2^{1/2 + \epsilon}$, $\max_{v \in V_2} |d_{2,v} - \bar d_2| \le Cn_1^{1/2 + \epsilon}$
	\item $\max \{n_1, n_2\} \le C(pq)^2(\min \left\{ n_1, n_2 \right\})^{1 + \epsilon}$
\item
	$  \frac{(1 - 2p)^2}{4pq} \left( 1 + \frac{5n_1}{6n_2} + \frac{5n_2}{6n_1} \right) \le a \log \max \left\{ n_1, n_2 \right\}$.
\end{romenumerate}
If $\min\{n_1, n_2\} \to \infty$, then uniformly for all such $\mathbf{d}_1,\mathbf{d}_2$
\begin{multline}

	|{\mathcal{R}}(\mathbf{d}_1,\mathbf{d}_2)| = \binom{n_1n_2}{p n_1n_2}^{-1} \prod_{v \in V_1}\binom {n_2}{d_{1,v}} \prod_{v \in V_2}\binom {n_1}{d_{2,v}} \times \\
	\times \exp \left[ -\frac{1}{2}\left( 1- \frac{D_1}{pqn_1n_2} \right)\left(1- \frac{D_2}{pqn_1n_2} \right) + O\left((\max\left\{ n_1,n_2 \right\})^{-b}\right) \right],
\end{multline}
where the constants implicit in the error term may depend on $a,b,C$.
